pub struct Guard {
    expected: Vec<u8>,
}

impl Guard {
    pub fn check(&self, presented: &[u8]) -> bool {
        if presented.len() != self.expected.len() {
            return false;
        }
        let mut diff = 0u8;
        for (a, b) in presented.iter().zip(&self.expected) {
            diff |= a ^ b;
        }
        diff == 0
    }
}

